# Destructive Digger (M20): {3}, {T}, Sacrifice an artifact or land: Draw a card.
# Cost shape: Portcullis Vine / Witch's Cauldron (CostSacrifice CHOOSE you-control); "artifact or land": FOr of TYPE_EQ (Smashing Success).
dig = ActivatedAbility(
    cost=Cost(
        parts=(
            CostManaGeneric(amount=QConst(value=3)),
            CostSacrifice(
                target=Selector(
                    count=QConst(value=1),
                    mode=SelectorMode.CHOOSE,
                    filter=FAnd(
                        children=(
                            FAtom(pred=FAtomPred.CONTROLLER_IS, who=ControllerRef.YOU),
                            FOr(
                                children=(
                                    FAtom(pred=FAtomPred.TYPE_EQ, string_value='Artifact'),
                                    FAtom(pred=FAtomPred.TYPE_EQ, string_value='Land'),
                                ),
                            ),
                        ),
                    ),
                    zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                ),
            ),
            CostTap(),
        ),
    ),
    effect=A(Verb.DRAW, {'amount': QConst(value=1), 'controller': ControllerRef.YOU}),
)
abilities = [dig, *compiled]
